SELECT 'utf8_locale_rows_needing_repair_expected_0_or_3' AS `check_name`,
       (SELECT COUNT(*) FROM `item_template_locale`
         WHERE `ID`=900300 AND `locale`='ruRU'
           AND (HEX(`Name`)<>'D09FD0BED187D0B5D182D0BDD18BD0B920D0B7D0BDD0B0D0BA'
             OR HEX(`Description`)<>'D0ADD182D0B820D0B7D0BDD0B0D0BAD0B820D0BCD0BED0B6D0BDD0BE20D0BED0B1D0BCD0B5D0BDD18FD182D18C20D0BDD0B020D180D0B0D0B7D0BBD0B8D187D0BDD0BED0B520D0BED180D183D0B6D0B8D0B520D0B820D0B4D0BED181D0BFD0B5D185D0B820D18320D182D0BED180D0B3D0BED0B2D186D0B5D0B220D181D0BDD0B0D180D18FD0B6D0B5D0BDD0B8D0B5D0BC2E'))
     + (SELECT COUNT(*) FROM `gameobject_template_locale`
         WHERE (`entry`=900501 AND `locale`='ruRU' AND HEX(`name`)<>'D09FD0BED180D182D0B0D0BB20D0B8D0B720D094D0B0D0BBD0B0D180D0B0D0BDD0B020D0BDD0B020D0BED181D182D180D0BED0B220D09AD0B5D0BBD18C27D094D0B0D0BDD0B0D181')
            OR (`entry`=900502 AND `locale`='ruRU' AND HEX(`name`)<>'D09FD0BED180D182D0B0D0BB20D0B220D0BDD0B0D187D0B0D0BBD0BE20D0BED181D182D180D0BED0B2D0B0')) AS `actual`;
SELECT 'client_cache_version_before' AS `check_name`, `cache_id` AS `actual` FROM `version` LIMIT 1;
